    if err:
        raise CliError(invalid_value("<mime>", err))
    typ, sub = s.split('/',1)
    return typ.lower()+"/"+sub.lower()


def mime_matches_pattern(pattern, mime):
    if pattern == mime: return True
    if pattern.endswith('/*') and '/' in pattern and '/' in mime:
        return pattern.split('/',1)[0] == mime.split('/',1)[0]
    return False


def system_apps():
    res={}
    seen_files=set()
    for d in app_dirs():
        if not d.exists(): continue
        try:
            files=sorted([p for p in d.rglob('*.desktop') if p.is_file()], key=lambda p: p.name)
        except Exception:
            files=[]
        for p in files:
            rp=str(p.resolve())
            if rp in seen_files: continue
            seen_files.add(rp)
