    sec = filtered_sections(unique=False)
    default=sec["Default Applications"]
    added=sec["Added Associations"]
    if mime in default and default[mime]: return default[mime]
    typ = mime.split('/',1)[0]
    pat = typ+'/*'
    if pat in default and default[pat]: return default[pat]
    if mime in added and added[mime]: return added[mime]
    sysapps=system_apps()
    if mime in sysapps and sysapps[mime]: return sysapps[mime]
    return []


