    sec.setdefault("Added Associations",{})
    write_mimeapps(sec)
    return 0


def cmd_unset(mime):
    sec=parse_mimeapps()
    sec.setdefault("Default Applications",{}).pop(mime, None)
    sec.setdefault("Added Associations",{})
    write_mimeapps(sec)
    return 0


def strip_exec_cmd(execstr):
    try:
        toks=shlex.split(execstr)
    except Exception:
        toks=execstr.split()
    out=[]
    for t in toks:
        if any(code in t for code in ('%f','%F','%u','%U')):
            if out and out[-1].startswith('-'):
                out.pop()
            continue
        out.append(t)
    return " ".join(out)


def cmd_get(mime, as_json=False):
    h=resolve_handler(mime)
    if as_json:
        _, vals=desktop_entry(h)
        obj={"handler": h, "name": vals.get('Name','') if vals else '', "cmd": strip_exec_cmd(vals.get('Exec','') if vals else '')}
        sys.stdout.write(json.dumps(obj, ensure_ascii=False, separators=(',',':'))+"\n")
    else:
        sys.stdout.write(h+"\n")
    return 0


def normalize_arg_url(a):
    m=re.match(r'^([A-Za-z][A-Za-z0-9+.-]*):(.*)$', a)
    if not m: return a
    scheme=m.group(1).lower()
    # For hierarchical URLs with authority and no path, urlparse/urlunparse adds a slash like url::Url.
    try:
        p=urlparse(a)
        if p.scheme in ('http','https') and p.netloc and p.path=='':
            return urlunparse((p.scheme, p.netloc, '/', p.params, p.query, p.fragment))
    except Exception:
        pass
    return a


def build_argv(execstr, args):
    try:
        toks=shlex.split(execstr)
    except Exception:
        toks=execstr.split()
    args=[normalize_arg_url(a) for a in args]
    out=[]; had=False
    for t in toks:
        if t in ('%f','%F','%u','%U'):
            out.extend(args); had=True
        elif any(code in t for code in ('%f','%F','%u','%U')):
