    ex=exec_line(handler)
    if not ex:
        raise RuntimeFailure(io_not_found())
    argv=build_argv(ex,args)
    if not argv:
        return 0
    try:
        p=subprocess.Popen(argv, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        p.wait()
    except FileNotFoundError:
        raise RuntimeFailure(io_not_found())
    except Exception as e:
        raise RuntimeFailure(f"Error: {e}\n")
    return 0


def cmd_launch(mime, args):
    h=resolve_handler(mime)
    return run_handler(h, args)


def is_urlish(s):
    return re.match(r'^[A-Za-z][A-Za-z0-9+.-]*:', s) is not None


def mime_for_path(s):
