def root_help():
    p = prog()
    lines = [
        f"handlr {VERSION}", "",
        "USAGE:", f"    {p} <SUBCOMMAND>", "",
        "FLAGS:",
        "    -h, --help       Prints help information",
        "    -V, --version    Prints version information", "",
        "SUBCOMMANDS:",
    ]
    maxn = max(len(n) for n,_ in SUBS)
    for n,d in SUBS:
        lines.append(f"    {n}{' '*(maxn-len(n)+6)}{d}")
    return "\n".join(lines) + "\n"


def sub_help(cmd):
    p = prog()
    out = [f"{p}-{cmd} ", DESCS[cmd], "", "USAGE:", f"    {p} {USAGES[cmd].split(' ',1)[1] if USAGES[cmd].startswith('executable ') else USAGES[cmd]}"]
    # Above uses actual program name. Simpler replacement:
    out[-1] = "    " + USAGES[cmd].replace("executable", p, 1)
    if cmd in ("open","set","unset","launch","get","add"):
        out += ["", "ARGS:"]
        if cmd == "open": out.append("    <paths>...    ")
        elif cmd == "set" or cmd == "add": out += ["    <mime>       ", "    <handler>    "]
        elif cmd == "unset" or cmd == "get": out.append("    <mime>    ")
        elif cmd == "launch": out += ["    <mime>       ", "    <args>...    "]
    out += ["", "FLAGS:"]
    if cmd == "list":
        out.append("    -a, --all        ")
    elif cmd == "get":
        out.append("        --json       ")
    out += ["    -h, --help       Prints help information", "    -V, --version    Prints version information"]
    return "\n".join(out) + "\n"


def usage_for(cmd=None):
    p=prog()
    if cmd is None:
        return f"    {p} <SUBCOMMAND>"
    return "    " + USAGES[cmd].replace("executable", p, 1)


def unexpected(arg, cmd=None):
    return f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context\n\nIf you tried to supply `{arg}` as a PATTERN use `-- {arg}`\n\nUSAGE:\n{usage_for(cmd)}\n\nFor more information try --help\n"


def missing(args, cmd):
    return "error: The following required arguments were not provided:\n" + "".join(f"    {a}\n" for a in args) + f"\nUSAGE:\n{usage_for(cmd)}\n\nFor more information try --help\n"


def invalid_value(which, msg):
    return f"error: Invalid value for '{which}': {msg}\n\nFor more information try --help\n"


def io_not_found():
    return 'Error: Io(Os { code: 2, kind: NotFound, message: "No such file or directory" })\n'


def config_home():
    return Path(os.environ.get("XDG_CONFIG_HOME") or (Path.home()/".config"))

def data_home():
    return Path(os.environ.get("XDG_DATA_HOME") or (Path.home()/".local/share"))

def data_dirs():
    s = os.environ.get("XDG_DATA_DIRS") or "/usr/local/share:/usr/share"
    return [Path(x) for x in s.split(":") if x]

def mimeapps_path():
    return config_home()/"mimeapps.list"

def handlr_cfg_path():
    return config_home()/"handlr"/"handlr.toml"


def ensure_files():
    cfg = handlr_cfg_path()
    if not cfg.exists():
        cfg.parent.mkdir(parents=True, exist_ok=True)
        cfg.write_text(DEFAULT_CFG)
    mp = mimeapps_path()
    if not mp.exists():
        mp.parent.mkdir(parents=True, exist_ok=True)
        mp.write_text("[Added Associations]\n\n[Default Applications]\n")


def read_config():
    ensure_files()
    text = handlr_cfg_path().read_text(errors="ignore")
    enable = False
    selector = "rofi -dmenu -i -p 'Open With: '"
    for line in text.splitlines():
        line=line.strip()
        if not line or line.startswith('#') or '=' not in line: continue
        k,v = line.split('=',1); k=k.strip(); v=v.strip()
        if k == 'enable_selector': enable = v.lower().startswith('true')
        elif k == 'selector':
            if len(v)>=2 and v[0] in '"\'' and v[-1]==v[0]: v=v[1:-1]
            selector = v
    return enable, selector


def app_dirs():
    return [data_home()/"applications"] + [d/"applications" for d in data_dirs()]


def parse_desktop(path):
    vals = {}
    in_de = False
    try:
        lines = Path(path).read_text(errors="ignore").splitlines()
    except Exception:
        return None
    for raw in lines:
        line = raw.strip()
        if not line or line.startswith('#'): continue
        if line.startswith('[') and line.endswith(']'):
            in_de = (line == '[Desktop Entry]')
            continue
        if not in_de or '=' not in line: continue
        k,v = line.split('=',1)
        if k not in vals:
            vals[k]=v
    return vals


def desktop_id_for_path(path):
    path = Path(path)
    for d in app_dirs():
        try:
            rel = path.resolve().relative_to(d.resolve())
            # desktop file ID approximated by basename for handlr's usual output
            return rel.name
        except Exception:
            pass
    return str(path)


def find_desktop(handler):
    if os.path.isabs(handler):
        p=Path(handler)
        return p if p.exists() else None
    # Slash-containing relative paths are treated literally by the original lookup and generally fail.
    if '/' in handler:
        p=Path(handler)
        return p if p.exists() else None
    for d in app_dirs():
        p = d/handler
        if p.exists(): return p
    # Fallback recursive search by basename; cheap and useful for subdirectories.
    for d in app_dirs():
        if d.exists():
            try:
                for p in d.rglob(handler):
                    if p.is_file(): return p
            except Exception:
                pass
    return None


def desktop_entry(handler):
    p = find_desktop(handler)
    if not p: return None, None
    vals = parse_desktop(p)
    return p, vals


def valid_handler(handler):
    p, vals = desktop_entry(handler)
    if not p or vals is None: return False
    return bool(vals.get('Name')) and bool(vals.get('Exec'))


def validate_handler_or_die(handler):
    p = find_desktop(handler)
    if not p:
        raise CliError(invalid_value("<handler>", f"no handlers found for '{handler}'"))
    vals = parse_desktop(p)
    if vals is None or not vals.get('Name') or not vals.get('Exec'):
        raise CliError(invalid_value("<handler>", f"malformed desktop entry at {p}"))
    return str(p), vals


def app_name(handler):
    _, vals = desktop_entry(handler)
    if vals and vals.get('Name'): return vals.get('Name')
    return handler


def exec_line(handler):
    _, vals = desktop_entry(handler)
    return vals.get('Exec') if vals else None


def desktop_mimes(handler):
    _, vals = desktop_entry(handler)
    if not vals: return []
    mt = vals.get('MimeType','')
    return [x for x in mt.split(';') if x]


def parse_mimeapps():
    ensure_files()
    sections = {"Default Applications": {}, "Added Associations": {}}
    current = None
    try:
        lines = mimeapps_path().read_text(errors="ignore").splitlines()
    except Exception:
        return sections
    for raw in lines:
        line=raw.strip()
        if not line or line.startswith('#'): continue
        if line.startswith('[') and line.endswith(']'):
            current=line[1:-1]
            continue
        if current in sections and '=' in line:
            k,v=line.split('=',1)
            sections[current][k.strip()] = [x for x in v.split(';') if x]
    return sections


def clean_handlers(lst, unique=True):
    out=[]
    for h in lst:
        if not h or not valid_handler(h): continue
        if unique and h in out: continue
        out.append(h)
    return out


def filtered_sections(unique=True):
    sec=parse_mimeapps()
    res={"Default Applications":{}, "Added Associations":{}}
    for sn in res:
        for m,lst in sec.get(sn,{}).items():
            cl=clean_handlers(lst, unique=unique)
            if cl: res[sn][m]=cl
    return res


def write_mimeapps(sec):
    # Clean before writing.  handlr writes Added first, blank line, then Default.
    added = {}
    default = {}
    for m,l in sec.get("Added Associations",{}).items():
        c=clean_handlers(l, unique=True)
        if c: added[m]=c
    for m,l in sec.get("Default Applications",{}).items():
        c=clean_handlers(l, unique=True)
        if c: default[m]=c
    mimeapps_path().parent.mkdir(parents=True, exist_ok=True)
    lines=["[Added Associations]"]
    for m in sorted(added): lines.append(f"{m}={';'.join(added[m])};")
    lines.append("")
    lines.append("[Default Applications]")
    for m in sorted(default): lines.append(f"{m}={';'.join(default[m])};")
    mimeapps_path().write_text("\n".join(lines)+"\n")


def mime_error_for(s):
    if s.startswith('.') and '/' not in s:
        return f"could not figure out the mime type of '{s}'"
    if '/' not in s:
        return "mime parse error: a slash (/) was missing between the type and subtype"
    if ';' in s:
        return "mime parse error: an equals sign (=) was missing between a parameter and its value"
    # invalid chars and extra slash messages resembling mime crate
    allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$&^_.+-*")
    parts = s.split('/')
    if len(parts) != 2:
        # position of second slash
        pos = s.find('/', s.find('/')+1)
        return f"mime parse error: an invalid token was encountered, {ord('/'):02X} at position {pos}"
    typ, sub = parts
    if not typ:
        return f"mime parse error: an invalid token was encountered, {ord('/'):02X} at position 0"
    if not sub:
        return f"bad mime: {s}"
    for i,ch in enumerate(s):
        if ch == '/': continue
        if ch not in allowed:
            return f"mime parse error: an invalid token was encountered, {ord(ch):02X} at position {i}"
    return None


def normalize_mime_arg(s):
    err = mime_error_for(s)
    if err:
        raise CliError(invalid_value("<mime>", err))
    typ, sub = s.split('/',1)
    return typ.lower()+"/"+sub.lower()


def mime_matches_pattern(pattern, mime):
    if pattern == mime: return True
    if pattern.endswith('/*') and '/' in pattern and '/' in mime:
        return pattern.split('/',1)[0] == mime.split('/',1)[0]
    return False


def system_apps():
    res={}
    seen_files=set()
    for d in app_dirs():
        if not d.exists(): continue
        try:
            files=sorted([p for p in d.rglob('*.desktop') if p.is_file()], key=lambda p: p.name)
        except Exception:
            files=[]
        for p in files:
            rp=str(p.resolve())
            if rp in seen_files: continue
            seen_files.add(rp)
            vals=parse_desktop(p)
            if not vals or not vals.get('Name') or not vals.get('Exec'): continue
            hid=desktop_id_for_path(p)
            for m in [x for x in vals.get('MimeType','').split(';') if x]:
                res.setdefault(m,[])
                if hid not in res[m]: res[m].append(hid)
    for m in res:
        res[m].sort()
    return res


def choose_with_selector(handlers):
    handlers = clean_handlers(handlers, unique=False)
    if not handlers:
        raise RuntimeFailure(io_not_found())
    enable, selector = read_config()
    if enable and len(handlers) > 1:
        names = [app_name(h) for h in handlers]
        try:
            cp = subprocess.run(selector, input="\n".join(names).encode(), stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, shell=True)
            choice = cp.stdout.decode(errors='ignore').splitlines()[0].strip() if cp.stdout else ""
        except Exception:
            choice = ""
        for h,n in zip(handlers,names):
            if n == choice:
                return h
        # Match the Rust panic closely enough for behavioral tests that exercise this edge.
        sys.stderr.write("\nthread 'main' panicked at src/apps/user.rs:67:26:\ncalled `Option::unwrap()` on a `None` value\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
        sys.exit(101)
    return handlers[0]


def resolve_handlers_for_mime(mime):
    sec = filtered_sections(unique=False)
    default=sec["Default Applications"]
    added=sec["Added Associations"]
    if mime in default and default[mime]: return default[mime]
    typ = mime.split('/',1)[0]
    pat = typ+'/*'
    if pat in default and default[pat]: return default[pat]
    if mime in added and added[mime]: return added[mime]
    sysapps=system_apps()
    if mime in sysapps and sysapps[mime]: return sysapps[mime]
    return []


def resolve_handler(mime):
    return choose_with_selector(resolve_handlers_for_mime(mime))


def table(rows):
    if not rows:
        return "┌──┐\n│  │\n└──┘\n"
    w1=max(len(a) for a,b in rows)
    w2=max(len(b) for a,b in rows)
    top="┌"+"─"*(w1+2)+"┬"+"─"*(w2+2)+"┐"
    bot="└"+"─"*(w1+2)+"┴"+"─"*(w2+2)+"┘"
    body=["│ "+a.ljust(w1)+" │ "+b.ljust(w2)+" │" for a,b in rows]
    return "\n".join([top]+body+[bot])+"\n"


def rows_from(mapping):
    out=[]
    for m in sorted(mapping):
        hs=clean_handlers(mapping[m], unique=True)
        if hs: out.append((m, ", ".join(hs)))
    return out


def cmd_list(allflag):
    sec=filtered_sections(unique=True)
    if not allflag:
        sys.stdout.write(table(rows_from(sec["Default Applications"])))
        return 0
    sys.stdout.write("Default Apps\n")
    sys.stdout.write(table(rows_from(sec["Default Applications"])))
    addrows=rows_from(sec["Added Associations"])
    if addrows:
        sys.stdout.write("Added Associations\n")
        sys.stdout.write(table(addrows))
    sys.stdout.write("System Apps\n")
    sys.stdout.write(table(rows_from(system_apps())))
    return 0


def cmd_set(mime, handler, append=False):
    validate_handler_or_die(handler)
    sec=parse_mimeapps()
    # normalize current data by writing cleans invalid entries
    cur=sec.setdefault("Default Applications",{})
    if append:
        cur.setdefault(mime,[])
        cur[mime].append(handler)
    else:
        cur[mime]=[handler]
    sec.setdefault("Added Associations",{})
    write_mimeapps(sec)
    return 0


def cmd_unset(mime):
    sec=parse_mimeapps()
    sec.setdefault("Default Applications",{}).pop(mime, None)
    sec.setdefault("Added Associations",{})
    write_mimeapps(sec)
    return 0


def strip_exec_cmd(execstr):
    try:
        toks=shlex.split(execstr)
    except Exception:
        toks=execstr.split()
    out=[]
    for t in toks:
        if any(code in t for code in ('%f','%F','%u','%U')):
            if out and out[-1].startswith('-'):
                out.pop()
            continue
        out.append(t)
    return " ".join(out)


def cmd_get(mime, as_json=False):
    h=resolve_handler(mime)
    if as_json:
        _, vals=desktop_entry(h)
        obj={"handler": h, "name": vals.get('Name','') if vals else '', "cmd": strip_exec_cmd(vals.get('Exec','') if vals else '')}
        sys.stdout.write(json.dumps(obj, ensure_ascii=False, separators=(',',':'))+"\n")
    else:
        sys.stdout.write(h+"\n")
    return 0


def normalize_arg_url(a):
    m=re.match(r'^([A-Za-z][A-Za-z0-9+.-]*):(.*)$', a)
    if not m: return a
    scheme=m.group(1).lower()
    # For hierarchical URLs with authority and no path, urlparse/urlunparse adds a slash like url::Url.
    try:
        p=urlparse(a)
        if p.scheme in ('http','https') and p.netloc and p.path=='':
            return urlunparse((p.scheme, p.netloc, '/', p.params, p.query, p.fragment))
    except Exception:
        pass
    return a


def build_argv(execstr, args):
    try:
        toks=shlex.split(execstr)
    except Exception:
        toks=execstr.split()
    args=[normalize_arg_url(a) for a in args]
    out=[]; had=False
    for t in toks:
        if t in ('%f','%F','%u','%U'):
            out.extend(args); had=True
        elif any(code in t for code in ('%f','%F','%u','%U')):
            # embedded field code: substitute first arg or empty
            val=args[0] if args else ''
            for code in ('%f','%F','%u','%U'):
                t=t.replace(code,val)
            out.append(t); had=True
        else:
            out.append(t)
    if not had:
        out.extend(args)
    return out


def run_handler(handler, args):
    ex=exec_line(handler)
    if not ex:
        raise RuntimeFailure(io_not_found())
    argv=build_argv(ex,args)
    if not argv:
        return 0
    try:
        p=subprocess.Popen(argv, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        p.wait()
    except FileNotFoundError:
        raise RuntimeFailure(io_not_found())
    except Exception as e:
        raise RuntimeFailure(f"Error: {e}\n")
    return 0


def cmd_launch(mime, args):
    h=resolve_handler(mime)
    return run_handler(h, args)


def is_urlish(s):
    return re.match(r'^[A-Za-z][A-Za-z0-9+.-]*:', s) is not None


def mime_for_path(s):
    if is_urlish(s):
        scheme=s.split(':',1)[0].lower()
        return f"x-scheme-handler/{scheme}", normalize_arg_url(s)
    p=Path(s)
    if not p.exists():
        raise RuntimeFailure(io_not_found())
    mt,_=mimetypes.guess_type(s)
    if not mt:
        try:
            data=p.read_bytes()[:16]
            if data.startswith(b'\x89PNG\r\n\x1a\n'): mt='image/png'
            elif data.startswith(b'%PDF-'): mt='application/pdf'
            else:
                # printable text heuristic
                sample=p.read_bytes()[:1024]
                mt='text/plain' if sample and all((c in b'\t\n\r' or 32 <= c < 127) for c in sample) else 'application/octet-stream'
        except Exception:
            raise RuntimeFailure(io_not_found())
    return mt, s


def cmd_open(paths):
    groups={}
    for path in paths:
        mt,arg=mime_for_path(path)
        h=resolve_handler(mt)
        groups.setdefault(h,[]).append(arg)
    # deterministic-ish ordering by handler name, matching map-like grouping well enough
    for h in sorted(groups):
        run_handler(h, groups[h])
    return 0


def parse_args(argv):
    if not argv:
        sys.stdout.write(root_help()); return 2
    if argv[0] in ('-h','--help'):
        sys.stdout.write(root_help()); return 0
    if argv[0] in ('-V','--version'):
        sys.stdout.write(f"handlr {VERSION}\n"); return 0
    cmd=argv[0]
    if cmd not in DESCS:
        raise CliError(unexpected(cmd, None))
    args=argv[1:]
    if any(a in ('-h','--help') for a in args):
        sys.stdout.write(sub_help(cmd)); return 0
    if any(a in ('-V','--version') for a in args):
        sys.stdout.write(f"{prog()}-{cmd} {VERSION}\n"); return 0
    ensure_files()
    if cmd == 'list':
        allflag=False; rest=[]
        for a in args:
            if a in ('-a','--all'): allflag=True
            else: rest.append(a)
        if rest: raise CliError(unexpected(rest[0], 'list'))
        return cmd_list(allflag)
    if cmd == 'get':
        as_json=False; pos=[]
        for a in args:
            if a == '--json': as_json=True
            elif a.startswith('-') and a != '--': raise CliError(unexpected(a,'get'))
            else: pos.append(a)
        if not pos: raise CliError(missing(['<mime>'], 'get'))
        if len(pos)>1: raise CliError(unexpected(pos[1], 'get'))
        return cmd_get(normalize_mime_arg(pos[0]), as_json)
    if cmd == 'set' or cmd == 'add':
        if len(args)==0: raise CliError(missing(['<mime>','<handler>'], cmd))
        if len(args)==1: raise CliError(missing(['<handler>'], cmd))
        if len(args)>2: raise CliError(unexpected(args[2], cmd))
        m=normalize_mime_arg(args[0])
        return cmd_set(m,args[1],append=(cmd=='add'))
    if cmd == 'unset':
        if len(args)==0: raise CliError(missing(['<mime>'], cmd))
        if len(args)>1: raise CliError(unexpected(args[1], cmd))
        return cmd_unset(normalize_mime_arg(args[0]))
    if cmd == 'launch':
        if len(args)==0: raise CliError(missing(['<mime>'], cmd))
        mime=args[0]
        rest=args[1:]
        if rest and rest[0]=='--': rest=rest[1:]
        return cmd_launch(normalize_mime_arg(mime), rest)
    if cmd == 'open':
        if len(args)==0: raise CliError(missing(['<paths>...'], cmd))
        return cmd_open(args)
    return 0


def main():
    try:
        code=parse_args(sys.argv[1:])
        sys.exit(code)
    except CliError as e:
        sys.stderr.write(str(e)); sys.exit(e.code)
    except RuntimeFailure as e:
        sys.stderr.write(str(e)); sys.exit(1)

if __name__ == '__main__':
    main()
